-- Migration 483: AA-1141 (S291, the P1 features of the Ecosystem status page) — the windows, factors, floors and limits
-- of alert ack / snooze / mute, the cost anomaly banner and the capacity forecast as settings.
--
-- Why. The S285 review of the status page (root docs/audits/2026-11-19-S285-session/ops-overview-v2-review.md, ideas
-- 2, 4 and 5) picked ack / snooze / mute with a reason, a capacity forecast and a cost anomaly banner by app x provider
-- x route as P1. Every window, factor, floor and limit they use is a setting (tech lead S279), never a code literal.
-- The stale factor of the freshness chips is the CIS 475 key cis.ops.status_stale_factor (reused, not repeated).
--
-- What:
--   1. Eleven rows in shared.setting_definition (seed block below, read by scripts/settings/gen_compiled_defaults.py into
--      shared/settings/compiled_defaults.json in this PR), app cis, area "ops", scope platform, impact low,
--      maker-checker, no evidence, no env override, enforced (shared/ops_status_thresholds.py names every key, the
--      settings-lint reader check). Defaults are the S285 review values:
--        cis.ops.status_ack_reason_min_chars        int characters 10-500, default 20
--        cis.ops.status_ack_hours                   int hours 1-168, default 24 (an Ack ends by itself after it)
--        cis.ops.status_mute_max_days               int days 1-30, default 7 (the furthest mute end time)
--        cis.ops.status_snooze_tomorrow_hour        int hour 0-23, default 8 ("until tomorrow", the viewer's clock)
--        cis.ops.status_snooze_choices_hours        list of hours, each in 1,2,3,4,6,8,12,24,48,72, default [1, 4]
--                                                   (the Snooze picker; the API refuses any other snooze length)
--        cis.ops.status_cost_anomaly_factor         numeric x 1.5-50, default 3 (an hour vs the median hour)
--        cis.ops.status_cost_anomaly_baseline_days  int days 1-30, default 7 (the days of that median)
--        cis.ops.status_cost_anomaly_floor_usd_h    usd per hour 0-100, default 0.10 (no anomaly at or below it)
--        cis.ops.status_forecast_window_days        int days 1-30, default 7 (the storage trend window)
--        cis.ops.status_forecast_warn_days          int days 1-365, default 30 (days left: warn)
--        cis.ops.status_forecast_crit_days          int days 1-180, default 7 (days left: critical)
--      Each seed row carries its plain label and its EN + VI operator guide (CIS 416 rule).
--   2. Register 483.
--
-- Behaviour on apply. None for running code: no value row is seeded and the code on main reads none of the keys. After
-- the code PR the page reads the defaults until an administrator changes them.
--
-- Class: CONTRACT (root ADR 0017 decision 3; no migrate directive line): config rows INSERTed into an existing table.
-- MIG-4: a migration-only PR together with CIS 482 (expand, the two tables), applied on Dev by Infra Migration Apply
-- when the job tables are idle (ADR 0017a), then the code PR (readiness requires 482 and 483). DM-6.1: no personal
-- data. DM-7.1: no new table.
--
-- Number. Owner main max (481) + 2, after 482 of the same CIS migration batch (482-483). If the owner main max + 1
-- differs at merge, renumber (git grep '483_' and '483' here, in tests/integration/test_aa1141_migration_482_483.py,
-- compiled_defaults.json's _generated line, api/core/readiness.py and docs/implementation-notes/AA-1141.md).
--
-- Locks. One INSERT ... ON CONFLICT of eleven rows (the definition guard trigger allows the file's role, cis_owner).
-- lock_timeout 5s. Re-runnable: ON CONFLICT DO NOTHING keeps a row an earlier run wrote.
--
-- Rollback (a new forward migration, after the code PR is reverted): DELETE the eleven keys' value rows first, then the
-- keys.

BEGIN;
SET LOCAL lock_timeout = '5s';

-- settings-seed:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted seed)
INSERT INTO shared.setting_definition
    (key, app, area, label, description, value_type, unit, min_value, max_value, allowed_values, default_value,
     scope_kind, impact, approval, evidence_required, env_override, cache_s, enforced, guide)
SELECT s.key, s.app, s.area, s.label, s.description, s.value_type, s.unit, s.min_value, s.max_value, s.allowed_values,
       s.default_value, s.scope_kind, s.impact, s.approval, s.evidence_required, s.env_override, s.cache_s, s.enforced,
       s.guide
  FROM jsonb_to_recordset($seed$
[
{"key": "cis.ops.status_ack_reason_min_chars", "app": "cis", "area": "ops", "label": "Status page: shortest reason to ack, snooze or mute", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) a person who acknowledges, snoozes or mutes a Needs-attention item must write a reason of at least this many characters (POST /admin/overview/status/acks); the reason is kept with the ack and in the audit log. The S285 review sets 20. Default 20.", "value_type": "int", "unit": "characters", "min_value": 10, "max_value": 500, "allowed_values": null, "default_value": 20, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The shortest written reason the page accepts when someone acknowledges, snoozes or mutes an alert.", "raise": "Longer reasons and better records, a little slower when many alerts fire.", "lower": "Faster to act, with thinner records of why an alert was set aside.", "when": "Keep 20 unless reviews of the ack trail show reasons that say too little.", "example": "With the default 20, \"deploy in progress, ok\" (22 characters) is accepted."}, "vi": {"what": "Độ dài tối thiểu của lý do mà trang chấp nhận khi ai đó xác nhận, tạm hoãn hoặc tắt tiếng một cảnh báo.", "raise": "Lý do dài hơn, hồ sơ rõ hơn, chậm hơn một chút khi nhiều cảnh báo cùng lúc.", "lower": "Thao tác nhanh hơn, hồ sơ lý do gác cảnh báo sơ sài hơn.", "when": "Giữ 20 trừ khi rà soát lịch sử xác nhận thấy lý do quá sơ sài.", "example": "Với mặc định 20, \"deploy in progress, ok\" (22 ký tự) được chấp nhận."}}},
{"key": "cis.ops.status_ack_hours", "app": "cis", "area": "ops", "label": "Status page: how long an Ack lasts (hours)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) an Ack of a Needs-attention item lasts this many hours and then ends by itself: if the item is still open it counts again in the verdict and shows as open. An alarm or rollout item also ends when the event ends. Snooze and mute have their own end times. Default 24.", "value_type": "int", "unit": "hours", "min_value": 1, "max_value": 168, "allowed_values": null, "default_value": 24, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many hours an acknowledged alert stays set aside before it counts as open again.", "raise": "An acknowledged alert stays quiet longer; a problem that drags on is seen again later.", "lower": "An acknowledged alert comes back sooner if it is still open.", "when": "Keep one working day; lower it during an incident so nothing stays set aside overnight.", "example": "With the default 24, an alert acked at 09:00 counts as open again at 09:00 the next day if it is still there."}, "vi": {"what": "Một cảnh báo đã xác nhận được gác bao nhiêu giờ trước khi tính là đang mở trở lại.", "raise": "Cảnh báo đã xác nhận im lâu hơn; vấn đề kéo dài được thấy lại muộn hơn.", "lower": "Cảnh báo đã xác nhận quay lại sớm hơn nếu vẫn còn.", "when": "Giữ một ngày làm việc; giảm khi có sự cố để không gì bị gác qua đêm.", "example": "Với mặc định 24, cảnh báo xác nhận lúc 09:00 tính là mở lại lúc 09:00 hôm sau nếu vẫn còn."}}},
{"key": "cis.ops.status_mute_max_days", "app": "cis", "area": "ops", "label": "Status page: longest mute (days)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) a person who mutes a Needs-attention item picks an end time; the API refuses an end time more than this many days ahead, so no alert is muted for good. Default 7.", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 30, "allowed_values": null, "default_value": 7, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The furthest end time a person may pick when muting an alert.", "raise": "Longer mutes are allowed, for a known issue that waits on a fix; a forgotten mute hides a problem longer.", "lower": "Mutes end sooner and must be renewed with a new reason.", "when": "Keep one week; raise it only for a known issue with a planned fix date.", "example": "With the default 7, a mute set on 24/11 can end on 01/12 at the latest."}, "vi": {"what": "Thời điểm kết thúc xa nhất mà một người được chọn khi tắt tiếng một cảnh báo.", "raise": "Cho phép tắt tiếng lâu hơn cho lỗi đã biết đang chờ sửa; nếu quên thì lỗi bị che lâu hơn.", "lower": "Tắt tiếng hết sớm hơn và phải đặt lại kèm lý do mới.", "when": "Giữ một tuần; chỉ tăng cho lỗi đã biết có ngày sửa dự kiến.", "example": "Với mặc định 7, tắt tiếng đặt ngày 24/11 kết thúc muộn nhất ngày 01/12."}}},
{"key": "cis.ops.status_snooze_tomorrow_hour", "app": "cis", "area": "ops", "label": "Status page: hour \"snooze until tomorrow\" ends", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) \"Snooze until tomorrow\" ends at this hour of the next day on the clock of the person who snoozes (0-23). Default 8.", "value_type": "int", "unit": "hour", "min_value": 0, "max_value": 23, "allowed_values": null, "default_value": 8, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The hour of the next morning at which \"snooze until tomorrow\" ends, on your own clock.", "raise": "Snoozed alerts come back later in the morning.", "lower": "Snoozed alerts come back earlier, before the working day starts.", "when": "Set it to when the person on duty starts the day.", "example": "With the default 8, an alert snoozed at 22:00 comes back at 08:00 the next day."}, "vi": {"what": "Giờ sáng hôm sau mà \"tạm hoãn tới mai\" kết thúc, theo đồng hồ của chính bạn.", "raise": "Cảnh báo tạm hoãn quay lại muộn hơn trong buổi sáng.", "lower": "Cảnh báo tạm hoãn quay lại sớm hơn, trước giờ làm.", "when": "Đặt theo giờ người trực bắt đầu ngày làm việc.", "example": "Với mặc định 8, cảnh báo tạm hoãn lúc 22:00 quay lại lúc 08:00 hôm sau."}}},
{"key": "cis.ops.status_snooze_choices_hours", "app": "cis", "area": "ops", "label": "Status page: snooze lengths offered (hours)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) the Snooze picker of a Needs-attention item offers these lengths in hours, each one of 1, 2, 3, 4, 6, 8, 12, 24, 48 or 72, next to \"until tomorrow\" (cis.ops.status_snooze_tomorrow_hour). The API refuses a snooze whose end time is none of them (POST /admin/overview/status/acks). An empty list leaves only \"until tomorrow\". Default [1, 4].", "value_type": "list", "unit": "hours", "min_value": null, "max_value": null, "allowed_values": [1, 2, 3, 4, 6, 8, 12, 24, 48, 72], "default_value": [1, 4], "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The snooze lengths, in hours, the page offers when someone snoozes an alert (\"until tomorrow\" is always offered too).", "raise": "Longer choices let an alert stay quiet for most of a shift; a problem that drags on is seen again later.", "lower": "Short choices only: a snoozed alert comes back soon and must be snoozed again if it is still expected.", "when": "Match the choices to how long typical known noise lasts, for example a deploy or a planned wave.", "example": "With the default [1, 4], the picker offers 1 h, 4 h and until tomorrow; adding 12 offers a 12 h snooze too."}, "vi": {"what": "Các độ dài tạm hoãn (giờ) mà trang đưa ra khi ai đó tạm hoãn một cảnh báo (luôn có thêm \"tới mai\").", "raise": "Lựa chọn dài hơn cho phép cảnh báo im gần hết một ca; vấn đề kéo dài được thấy lại muộn hơn.", "lower": "Chỉ lựa chọn ngắn: cảnh báo tạm hoãn quay lại sớm và phải tạm hoãn lại nếu vẫn còn.", "when": "Chọn theo thời gian mà nhiễu đã biết thường kéo dài, ví dụ một lần deploy hay một wave đã lên kế hoạch.", "example": "Với mặc định [1, 4], trang đưa ra 1 giờ, 4 giờ và tới mai; thêm 12 thì có thêm tạm hoãn 12 giờ."}}},
{"key": "cis.ops.status_cost_anomaly_factor", "app": "cis", "area": "ops", "label": "Status page: AI spend anomaly factor", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) the cost anomaly banner shows an app x provider x route (connection) whose AI spend in one hour is above this many times its median hour over cis.ops.status_cost_anomaly_baseline_days days (hours with no spend count as 0) and above cis.ops.status_cost_anomaly_floor_usd_h. Read from the hourly usage rollup (shared.ai_usage_hourly), so the grouping stays the same when a route moves between the vendor API and Bedrock. Default 3.", "value_type": "numeric", "unit": "x", "min_value": 1.5, "max_value": 50, "allowed_values": null, "default_value": 3, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many times its usual hourly AI spend one app on one provider route must reach before the page shows a cost anomaly banner.", "raise": "Only big jumps show a banner; a slow rise is seen later.", "lower": "Smaller jumps show a banner, including busy hours of a planned wave.", "when": "Raise it while waves run often; lower it when spend is flat and any jump is suspect.", "example": "With the default 3, a route that usually spends 0.20 USD an hour shows a banner at 0.61 USD in one hour."}, "vi": {"what": "Chi phí AI trong một giờ của một app trên một route nhà cung cấp phải gấp bao nhiêu lần mức thường ngày để trang hiện băng cảnh báo bất thường.", "raise": "Chỉ bước nhảy lớn mới hiện băng; tăng chậm được thấy muộn hơn.", "lower": "Bước nhảy nhỏ cũng hiện băng, kể cả giờ bận của một wave đã lên kế hoạch.", "when": "Tăng khi wave chạy thường xuyên; giảm khi chi phí đều và bước nhảy nào cũng đáng ngờ.", "example": "Với mặc định 3, route thường tốn 0,20 USD một giờ sẽ hiện băng khi lên 0,61 USD trong một giờ."}}},
{"key": "cis.ops.status_cost_anomaly_baseline_days", "app": "cis", "area": "ops", "label": "Status page: days of usual AI spend for the anomaly banner", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) the usual hourly AI spend of an app x provider x route is its median hour over this many UTC days before the current hour (hours with no spend count as 0); the cost anomaly banner compares each recent hour with it. The S285 review reads 7 days. Default 7.", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 30, "allowed_values": null, "default_value": 7, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many days of past AI spend the page uses to know the usual spend per hour of each app and route.", "raise": "A steadier usual spend that a few busy days do not move, learned slower after a lasting change.", "lower": "The usual spend follows recent use sooner; a busy day can hide a jump right after it.", "when": "Keep a full week so weekdays and weekends both count.", "example": "With the default 7, an hour on 24/11 is compared with the median hour from 17/11 to 24/11."}, "vi": {"what": "Số ngày chi phí AI trước đó mà trang dùng để biết mức chi thường ngày theo giờ của từng app và route.", "raise": "Mức thường ngày ổn định hơn, vài ngày bận không làm lệch, nhưng học chậm hơn sau thay đổi lâu dài.", "lower": "Mức thường ngày theo sát gần đây hơn; một ngày bận có thể che bước nhảy ngay sau đó.", "when": "Giữ trọn một tuần để tính cả ngày thường và cuối tuần.", "example": "Với mặc định 7, một giờ ngày 24/11 được so với giờ trung vị từ 17/11 tới 24/11."}}},
{"key": "cis.ops.status_cost_anomaly_floor_usd_h", "app": "cis", "area": "ops", "label": "Status page: smallest hourly AI spend that can be an anomaly", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) an app x provider x route spending at most this many USD in one hour never shows in the cost anomaly banner, whatever its usual spend, so a route that is usually idle does not raise one on its first cents. Default 0.10 USD per hour.", "value_type": "usd", "unit": "USD/hour", "min_value": 0, "max_value": 100, "allowed_values": null, "default_value": 0.1, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The lowest spend in one hour at which the page can call a route's AI spend abnormal.", "raise": "Small routes never show a banner; only real money does.", "lower": "Even a few cents an hour can show a banner on a route that is usually idle.", "when": "Keep it near the hourly cost you would not act on.", "example": "With the default 0.10, an idle route spending 0.05 USD in an hour shows no banner."}, "vi": {"what": "Mức chi trong một giờ thấp nhất mà trang có thể coi chi phí AI của một route là bất thường.", "raise": "Route nhỏ không bao giờ hiện băng; chỉ số tiền đáng kể mới hiện.", "lower": "Chỉ vài cent một giờ cũng có thể hiện băng trên một route thường không dùng.", "when": "Giữ gần mức chi theo giờ mà bạn sẽ không xử lý.", "example": "Với mặc định 0,10, route ít dùng chi 0,05 USD trong một giờ không hiện băng."}}},
{"key": "cis.ops.status_forecast_window_days", "app": "cis", "area": "ops", "label": "Status page: days of trend for the capacity forecast", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) the capacity forecast fits the trend of RDS free storage over this many days (one CloudWatch FreeStorageSpace read per day point, cached 6 hours) to say in how many days it reaches its limit; the AI caps use the month to date. Default 7.", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 30, "allowed_values": null, "default_value": 7, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many past days the page looks at to project when database storage runs out.", "raise": "A steadier projection that one busy day does not move, slower to follow a change in growth.", "lower": "The projection follows recent growth sooner but jumps more.", "when": "Keep a week; lower it right after a large data load so the projection follows the new pace.", "example": "With the default 7, the forecast on 24/11 uses the free storage from 17/11 to 24/11."}, "vi": {"what": "Trang xem bao nhiêu ngày trước để dự báo khi nào dung lượng database hết.", "raise": "Dự báo ổn định hơn, một ngày bận không làm lệch, nhưng chậm theo thay đổi tốc độ tăng.", "lower": "Dự báo theo sát tốc độ gần đây hơn nhưng dao động nhiều hơn.", "when": "Giữ một tuần; giảm ngay sau một đợt nạp dữ liệu lớn để dự báo theo nhịp mới.", "example": "Với mặc định 7, dự báo ngày 24/11 dùng dung lượng trống từ 17/11 tới 24/11."}}},
{"key": "cis.ops.status_forecast_warn_days", "app": "cis", "area": "ops", "label": "Status page: capacity forecast warn (days left)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) a capacity forecast (RDS free storage, an AI connection's monthly cap) that reaches its limit in this many days or fewer is coloured warn. Default 30.", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 365, "allowed_values": null, "default_value": 30, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many days before a limit the capacity forecast turns amber.", "raise": "Earlier warnings, more time to plan; more amber rows that may never matter.", "lower": "Fewer amber rows, less time to act.", "when": "Keep about a month: storage growth and monthly caps are planned monthly.", "example": "With the default 30, storage expected to run out in 25 days shows amber."}, "vi": {"what": "Còn bao nhiêu ngày tới giới hạn thì dự báo dung lượng chuyển màu vàng.", "raise": "Cảnh báo sớm hơn, nhiều thời gian chuẩn bị; nhiều dòng vàng có thể không bao giờ thành vấn đề.", "lower": "Ít dòng vàng hơn, ít thời gian xử lý hơn.", "when": "Giữ khoảng một tháng: dung lượng và trần chi hằng tháng được lên kế hoạch theo tháng.", "example": "Với mặc định 30, dung lượng dự kiến hết sau 25 ngày hiện màu vàng."}}},
{"key": "cis.ops.status_forecast_crit_days", "app": "cis", "area": "ops", "label": "Status page: capacity forecast critical (days left)", "description": "On the Ecosystem status page (/admin/overview, api/services/ops_status/) a capacity forecast that reaches its limit in this many days or fewer is coloured critical and listed in Needs attention (SEV3). A value above the warn days is lowered to it. Default 7.", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 180, "allowed_values": null, "default_value": 7, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many days before a limit the capacity forecast turns red and asks for action.", "raise": "Earlier red rows and earlier action items.", "lower": "Red only when the limit is very close.", "when": "Keep a week: enough to raise storage or a cap with a reviewed change.", "example": "With the default 7, an AI connection expected to reach its monthly cap in 5 days shows red."}, "vi": {"what": "Còn bao nhiêu ngày tới giới hạn thì dự báo dung lượng chuyển đỏ và cần xử lý.", "raise": "Dòng đỏ và việc cần làm xuất hiện sớm hơn.", "lower": "Chỉ đỏ khi giới hạn đã rất gần.", "when": "Giữ một tuần: đủ để tăng dung lượng hoặc trần chi qua một thay đổi có duyệt.", "example": "Với mặc định 7, kết nối AI dự kiến chạm trần tháng sau 5 ngày hiện màu đỏ."}}}
]
